import { useEffect, useState } from 'react';
import {defaultPreferences,preferencesSchema,type WorkbenchLayoutContext}from'@aork/contracts/workbench';
import type { ClientPluginContext, ViewProps } from '@aork/sdk/client';
function Layout({runtime}:ViewProps){const[preferences,setPreferences]=useState(defaultPreferences);const[hash,setHash]=useState(location.hash);useEffect(()=>runtime.observeSnapshot('workbench.preferences',{}, {next:value=>setPreferences(preferencesSchema.parse(value))},{owners:['workbench']}),[]);useEffect(()=>{const changed=()=>setHash(location.hash);addEventListener('hashchange',changed);return()=>removeEventListener('hashchange',changed);},[]);const context:WorkbenchLayoutContext={preferences,narrow:false,save(update){const next={...preferences,...update};setPreferences(next);void runtime.command('workbench.savePreferences',next,crypto.randomUUID());}};const selected=new URLSearchParams(hash.slice(1));return <div style={{height:'100dvh',display:'grid',gridTemplateColumns:preferences.sidebarOpen?'280px minmax(0,1fr)':'minmax(0,1fr)',fontFamily:'var(--aork-font)',color:'var(--aork-text)',background:'var(--aork-surface)'}}>{preferences.sidebarOpen&&<aside>{runtime.renderView('aork.workbench.sidebar@1',context)}</aside>}<section style={{overflow:'auto'}}><div style={{height:44,display:'flex',gap:12}}><strong>独立完整布局</strong>{runtime.renderView('aork.workbench.header-view@1',context)}</div><div style={{display:'flex'}}><main style={{minWidth:0,flex:1}}>{runtime.renderView('aork.workbench.main@1',context)}</main>{selected.get('session')&&preferences.filesOpen&&<aside style={{width:360}}>{runtime.renderView('aork.workspace.files@1',{panel:true,wide:false})}</aside>}</div></section></div>;}
function Messages({ runtime }: ViewProps) { const selected = new URLSearchParams(location.hash.slice(1)); const sessionId = selected.get('session'); const [value, setValue] = useState<any>(); useEffect(() => { if (!sessionId)
    return; return runtime.observeSnapshot('sessions.timeline', { sessionId }, { next: setValue }, { owners: ['sessions'] }); }, [sessionId]); if (selected.get('broken') === '1')
    throw Error('Controlled independent view failure'); return <section aria-label="独立消息"><h3>独立可替换消息</h3>{value?.turns.map((turn: any) => { const text = value.messages.filter((message: any) => message.turnId === turn.id && message.role === 'agent').map((message: any) => message.text).join(''); const reply = value.completedReplies.find((item: any) => item.turnId === turn.id); const content = <p>{text}</p>; return <article key={turn.id}>{reply ? runtime.renderView('aork.workbench.read-tracker@1', { sessionId, activityId: reply.activityId, content }) : content}</article>; })}</section>; }
function Menu({ runtime }: ViewProps) { return <nav aria-label="独立菜单">{runtime.renderExtensions('aork.workbench.menu-items@1')}</nav>; }
function Notifications({ runtime }: ViewProps) { const [count, setCount] = useState<number>(); useEffect(() => runtime.observeSnapshot<any>('workbench.unread', {}, { next: value => setCount(value.count) }, { owners: ['workbench'] }), []); return <div aria-label="独立通知">独立未读 {count}{runtime.renderExtensions('aork.workbench.notification-sources@1')}</div>; }
export function activate(context: ClientPluginContext) { context.registerView('layout', Layout); context.registerView('messages', Messages); context.registerView('menu', Menu); context.registerView('notifications', Notifications); context.registerExtension('alpha', () => <button>扩展 Alpha</button>); context.registerExtension('beta', () => <button>扩展 Beta</button>); context.registerExtension('notice', () => <span>扩展通知</span>); }
